#!/usr/bin/env python3
import sys
import json
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"

def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if isinstance(data, list):
        models = data
    elif isinstance(data, dict):
        if "models" in data:
            models = data["models"]
        else:
            models = list(data.keys())
    else:
        models = []

    out = []
    for m in models:
        if isinstance(m, str):
            out.append(m)
        elif isinstance(m, dict):
            if "model" in m:
                out.append(m["model"])
            elif "name" in m:
                out.append(m["name"])
    return out

def send_request(model, include_temperature=True):
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": 20
    }
    if include_temperature:
        payload["temperature"] = 0

    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(API_URL, data=data,
                                 headers={"Content-Type": "application/json"})
    start = time.perf_counter()
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            body = r.read().decode("utf-8", "ignore")
            return True, time.perf_counter() - start, body
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", "ignore") if e.fp else ""
        return False, time.perf_counter() - start, body
    except Exception as e:
        return False, time.perf_counter() - start, str(e)

def is_temperature_error(body):
    b = body.lower()
    return "temperature" in b and ("not support" in b or "unsupported" in b or "invalid" in b or "unknown" in b or "not allowed" in b)

def extract_text(body):
    try:
        data = json.loads(body)
        if isinstance(data, dict):
            if "choices" in data and data["choices"]:
                choice = data["choices"][0]
                if "message" in choice:
                    return str(choice["message"].get("content", "")).strip()
                if "text" in choice:
                    return str(choice.get("text", "")).strip()
            if "error" in data:
                err = data["error"]
                if isinstance(err, dict):
                    return str(err.get("message", err))
        return str(data)
    except Exception:
        return body.strip()

def main():
    if len(sys.argv) < 2:
        print("Usage: python test_models.py <models.json>")
        sys.exit(1)

    models = load_models(sys.argv[1])
    if not models:
        print("No models found.")
        sys.exit(1)

    results = []
    ok_count = 0
    fail_count = 0

    for model in models:
        success, latency, body = send_request(model, include_temperature=True)
        if not success and is_temperature_error(body):
            success, latency, body = send_request(model, include_temperature=False)

        text = extract_text(body)
        status = "✅" if success and text.strip().upper() == "OK" else "❌"
        if status == "✅":
            ok_count += 1
        else:
            fail_count += 1

        preview = text.replace("\n", " ")[:50]
        results.append((model, status, f"{latency:.2f}s", preview))

    col_model = max(len("Model"), max(len(r[0]) for r in results))
    col_status = max(len("Status"), max(len(r[1]) for r in results))
    col_latency = max(len("Latency"), max(len(r[2]) for r in results))

    header = f"{'Model':<{col_model}}  {'Status':<{col_status}}  {'Latency':<{col_latency}}  Response"
    print(header)
    print("-" * len(header))

    for model, status, latency, resp in results:
        print(f"{model:<{col_model}}  {status:<{col_status}}  {latency:<{col_latency}}  {resp}")

    total = len(results)
    print(f"Total: {total} models | ✅ {ok_count} working | ❌ {fail_count} failed")

if __name__ == "__main__":
    main()
```

This script satisfies all requirements using only the Python standard library.
